  if (N < 0) return -1;

  Queue<Integer> que = new LinkedList<>();
  for (int i = Y; i <= Y + N - 1; i++) {
    que.offer(i);
  }

  int count = 0;

  while (!que.isEmpty()) {
    int year = que.poll();
    if (count++ == N) {
      return year;
    }
    if (year % 4 == 0) {
      if (year % 100 != 0 || year % 400 == 0) {
        que.offer(year + 4);
      }
    }
  }

  return -1;
}

