public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        result.add(Collections.singletonList(nums[0]));
    } else {
        for (int i = 0; i < nums.length; i++) {
            List<List<Integer>> subPermutations = permute(Arrays.copyOfRange(nums, 0, i)
                    .concat(Arrays.copyOfRange(nums, i + 1, nums.length)));
            for (List<Integer> subPermission : subPermutations) {
                subPermission.add(0, nums[i]);
                result.add(subPermission);
            }
        }
    }
    return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();
    if (nums.length == 1) {
      permutations.add(Arrays.asList(nums[0]));
      return permutations;
    }
    for (int i = 0; i < nums.length; i++) {
      int num = nums[i];
      List<Integer> subPermutations = permute(remove(nums, i));
      for (int j = 0; j < subPermutations.size(); j++) {
        List<Integer> newPermutation = new ArrayList<>(subPermutations.get(j));
        newPermutation.add(0, num);
        permutations.add(newPermutation);
      }
    }
    return permutations;
  }

private int[] remove(int[] nums, int i) {
    int[] newNums = new int[nums.length - 1];
    for (int j = 0, k = 0; j < nums.length; j++) {
      if (j == i) {
        continue;
      }
      newNums[k++] = nums[j];
    }
    return newNums;
  }

