public static int maxRegions(int N) {
   int maxRegions = 0;

   // Base case:
   // If N == 0, there is only one region (the entire plane).
   if (N == 0) {
      return 1;
   }

   // Recursive case:
   // Calculate the maximum number of regions for N-1 triangles.
   for (int i = 0; i < N; i++) {
      int remainingRegions = maxRegions(N-1);

      // If the current triangle does not touch the vertical line at x=i,
      // then we can have an additional region.
      if (i >= N-1 || (i > 0 && i < N-1 && Math.abs(i - N-1) <= 2)) {
         remainingRegions++;
      }

      maxRegions = Math.max(maxRegions, remainingRegions);
   }

   return maxRegions;
}

