    boolean[] visited = new boolean[n];
    // Initialize a queue to keep track of n-tersections to visit
    Queue<int[]> queue = new LinkedList<>();
    // Add the starting n-tersection to the queue
    queue.add(start);
    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection
        int[] current = queue.poll();
        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if(Arrays.equals(current, end)) {
            return "can be travelled";
        }
        // Mark the current n-tersection as visited
        visited[current[0] * n + current[1]] = true;
        // Loop through the paths
        for (int[] path : paths) {
            // If the current n-tersection is connected to the current path n-tersection
            if (current[0] * n + current[1] == path[0]) {
                // Add the current path n-tersection to the queue
                queue.add(path);
            }
        }
    }
    // If all n-tersections are visited and the ending n-tersection is not reached, return "cannot be travelled"
    return "cannot be travelled";
}

