public int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        int midValue = nums[mid];

        if (midValue == target) {
            return mid;
        }

        if (nums[left] <= midValue) {
            if (target < midValue) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (target > midValue) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

