public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Find the indices of the smallest and largest 5% of elements
    int smallest5PercentIndex = (int)(arr.length * 0.05);
    int largest5PercentIndex = arr.length - smallest5PercentIndex;

    // Calculate the sum of the remaining elements after removing the smallest and largest 5%
    int sum = 0;
    for (int i = smallest5PercentIndex; i < largest5PercentIndex; i++) {
        sum += arr[i];
    }

    // Return the mean with an error within 10^-5
    return (double)sum / (arr.length - 2 * smallest5PercentIndex);
}

public static double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the number of elements to remove from the smallest and largest 5%
    int numElementsToRemove = (int) Math.ceil(arr.length * 0.05);

    // Remove the smallest 5% of elements
    for (int i = 0; i < numElementsToRemove; i++) {
        arr[i] = 0;
    }

    // Remove the largest 5% of elements
    for (int i = arr.length - 1; i >= arr.length - numElementsToRemove; i--) {
        arr[i] = 0;
    }

    // Calculate the mean of the remaining elements
    int sum = 0;
    for (int i : arr) {
        if (i != 0) {
            sum += i;
        }
    }
    return (double) sum / arr.length - numElementsToRemove * 2;
}

public double trimMean(int[] arr) {
    // Sort the array in descending order
    Arrays.sort(arr);

    // Find the rank of the 5th percentile (smallest 5%) element
    int rank = (int) (0.95 * arr.length);

    // Find the sum of the elements greater than the 5th percentile element
    int sum = 0;
    for (int i = rank; i < arr.length; i++) {
        sum += arr[i];
    }

    // Find the mean of the remaining elements
    return sum / (arr.length - rank);
}

public boolean canArrange(int[] arr, int k) {
    // Initialize a hash map to keep track of the frequency of each element in the array
    HashMap<Integer, Integer> freq = new HashMap<>();
    for (int a : arr) {
        freq.put(a, freq.getOrDefault(a, 0) + 1);
    }

    // Iterate over the hash map and find the maximum frequency
    int maxFreq = 0;
    for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() > maxFreq) {
            maxFreq = entry.getValue();
        }
    }

    // Initialize a variable to keep track of the current sum
    int currSum = 0;
    for (int i = 0; i < arr.length / 2; i++) {
        // If the current sum is already divisible by k, we can skip this iteration
        if (currSum % k == 0) {
            continue;
        }

        // Find the element with the maximum frequency
        int maxFreqElement = -1;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() == maxFreq) {
                maxFreqElement = entry.getKey();
                break;
            }
        }

        // If no element with the maximum frequency exists, we cannot divide the array into pairs
        if (maxFreqElement == -1) {
            return false;
        }

        // Add the maximum frequency element to the current sum
        currSum += maxFreqElement;

        // Reduce the frequency of the maximum frequency element by 1
        freq.put(maxFreqElement, freq.get(maxFreqElement) - 1);
    }

    // If the current sum is divisible by k, we can divide the array into pairs
    if (currSum % k == 0) {
        return true;
    }
    return false;
}

public boolean canArrange(int[] arr, int k) {
    if (k == 0 || arr.length == 0) {
        return false;
    }
    // Identifier of the current pair
    int pairId = 0;
    // Set to keep track of the divisors of each pair
    Set<Integer> divisors = new HashSet<>();
    // Sum of all the pairs
    int pairSum = 0;
    // Loop through the array and assign each element to a pair
    for (int i = 0; i < arr.length; i++) {
        // If the current pair is finished, start a new one
        if (pairSum % k == 0) {
            pairId++;
        }
        // Add the current element to the pair
        pairSum += arr[i];
        // If the pair is divisible by k, add its divisors to the set
        if (pairSum % k == 0) {
            for (int d = 1; d <= k; d++) {
                if (pairSum % d == 0) {
                    divisors.add(d);
                }
            }
        }
    }
    // Check if all the divisors of the pairs are the same
    return divisors.size() == 1;
}

public boolean canArrange(int[] arr, int k) {
  if (arr.length % 2 != 0) {
    return false;
  }

  int n = arr.length / 2;
  int[] pairs = new int[n];

  for (int i = 0; i < n; i++) {
    pairs[i] = arr[i * 2] + arr[i * 2 + 1];
  }

  for (int num : pairs) {
    if (num % k != 0) {
      return false;
    }
  }

  return true;
}

