public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create an adjacency list to represent the graph
    List<List<Integer>> graph = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // Breadth-first search to determine the shortest path to the apples
    boolean[] visited = new boolean[n];
    int[] distance = new int[n];
    Arrays.fill(distance, -1);
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    distance[0] = 0;
    visited[0] = true;
    while (!queue.isEmpty()) {
        int curr = queue.remove();
        for (int neighbor : graph.get(curr)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                distance[neighbor] = distance[curr] + 1;
                queue.add(neighbor);
            }
        }
    }

    // Calculate the min time to collect all apples
    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && distance[i] != -1) {
            minTime = Math.max(minTime, distance[i]);
        }
    }
    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Key: node_id, time
    Map<Integer, Integer> nodeTimes = new HashMap<>();
    // initialize node 0 with time 0
    nodeTimes.put(0, 0);

    // BFS
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    while (!queue.isEmpty()) {
        int nodeId = queue.poll();
        if (hasApple[nodeId]) {
            // apple found, return immediately
            return nodeTimes.get(nodeId);
        }
        for (int neighbor : edges[nodeId]) {
            if (!nodeTimes.containsKey(neighbor)) {
                // neighbor not visited, add to queue and mark with time from parent node
                nodeTimes.put(neighbor, nodeTimes.get(nodeId) + 1);
                queue.offer(neighbor);
            }
        }
    }

    // no apple found, return 0
    return 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }
    int[] dist = new int[n];
    Arrays.fill(dist, -1);
    return dfs(graph, dist, 0, hasApple);
}

private int dfs(List<List<Integer>> graph, int[] dist, int node, boolean[] hasApple) {
    if (dist[node] != -1) {
        return dist[node];
    }
    dist[node] = 0;
    for (int neighbor : graph.get(node)) {
        if (hasApple[neighbor]) {
            dist[node] = 1 + Math.max(dfs(graph, dist, neighbor, hasApple), dist[node]);
        } else {
            dist[node] = 1 + Math.max(dfs(graph, dist, neighbor, hasApple), dist[node]);
        }
    }
    return dist[node];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>(n));
    }
    for (int i = 0; i < edges.length; i++) {
        int from = edges[i][0];
        int to = edges[i][1];
        graph.get(from).add(to);
        graph.get(to).add(from);
    }
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.reverseOrder());
    pq.offer(0);
    while (!pq.isEmpty()) {
        int curr = pq.poll();
        for (int neighbor : graph.get(curr)) {
            if (hasApple[neighbor] && dist[neighbor] > dist[curr] + 1) {
                dist[neighbor] = dist[curr] + 1;
                pq.offer(neighbor);
            }
        }
    }
    return dist[n - 1];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Edge case: if the tree has no apples, return 0
    if (!hasApple.isEmpty()) {
        return 0;
    }

    // Create a map of nodes to their children
    // and a map of nodes to their parents
    Map<Integer, List<Integer>> childrenMap = new HashMap<>();
    Map<Integer, Integer> parentMap = new HashMap<>();
    for (int[] edge : edges) {
        int parent = edge[0];
        int child = edge[1];
        childrenMap.putIfAbsent(parent, new ArrayList<>());
        childrenMap.get(parent).add(child);
        parentMap.put(child, parent);
    }

    // Create a queue of nodes to visit
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);

    // Create a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];

    // Loop through the queue until it's empty
    while (!queue.isEmpty()) {
        // Dequeue the front node
        int node = queue.poll();

        // If the node has an apple, return 1
        if (hasApple[node]) {
            return 1;
        }

        // Mark the node as visited
        visited[node] = true;

        // Enqueue the node's children
        for (Integer child : childrenMap.getOrDefault(node, Collections.emptyList())) {
            queue.offer(child);
        }
    }

    // If we get to this point, we've visited all nodes and didn't find any apples
    return -1;
}

public String sortString(String s) {
    char[] result = new char[s.length()];
    int index = 0;

    while (index < s.length()) {
        // Find the smallest character in s that is greater than the last character in result
        char smallest = s.charAt(index);
        for (int i = index + 1; i < s.length(); i++) {
            if (s.charAt(i) > smallest && s.charAt(i) < result[result.length - 1]) {
                smallest = s.charAt(i);
            }
        }
        // Append the smallest character to result
        result[index++] = smallest;

        // Find the largest character in s that is smaller than the last character in result
        char largest = s.charAt(index);
        for (int i = index + 1; i < s.length(); i++) {
            if (s.charAt(i) < largest && s.charAt(i) > result[result.length - 1]) {
                largest = s.charAt(i);
            }
        }
        // Append the largest character to result
        result[index++] = largest;
    }

    return new String(result);
}

public static String sortString(String s) {
    char[] array = s.toCharArray();
    char lastChar = ' ';
    StringBuilder result = new StringBuilder();
    while (result.length() < array.length) {
        boolean found = false;
        for (char c : array) {
            if (c < lastChar) {
                result.append(c);
                lastChar = c;
                found = true;
                break;
            }
        }
        if (!found) {
            for (int i = array.length - 1; i >= 0; i--) {
                if (array[i] > lastChar) {
                    result.append(array[i]);
                    lastChar = array[i];
                    found = true;
                    break;
                }
            }
        }
        if (!found) {
            break;
        }
    }
    return result.toString();
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < chars.length; i++) {
        char curr = chars[i];
        if (curr != sb.charAt(sb.length() - 1)) {
            sb.append(curr);
        }
        if (i < chars.length - 1 && curr > sb.charAt(sb.length() - 1)) {
            int index = -1;
            do {
                index++;
            } while (chars[index] != curr && index < chars.length - 1);
            if (index < chars.length - 1) {
                sb.append(chars[index]);
            }
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    char[] chars = s.toCharArray();

    // Step 1
    Arrays.sort(chars);

    // Step 2
    for (int i = 0; i < chars.length; i++) {
        char c = chars[i];
        if (result.length() == 0 || result.charAt(result.length() - 1) < c) {
            result.append(c);
        }
    }

    // Step 3
    for (int i = chars.length - 1; i >= 0; i--) {
        char c = chars[i];
        if (result.length() == 0 || result.charAt(result.length() - 1) > c) {
            result.append(c);
        }
    }

    return result.toString();
