public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        int minIndex = 0;
        int maxIndex = 0;
        char minChar = '\0';
        char maxChar = '\0';
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (minChar == '\0' || c < minChar) {
                minChar = c;
                minIndex = i;
            }
            if (maxChar == '\0' || c > maxChar) {
                maxChar = c;
                maxIndex = i;
            }
        }
        result.append(minChar);
        result.append(maxChar);
        s = s.substring(0, minIndex) + s.substring(minIndex + 1);
        s = s.substring(0, maxIndex) + s.substring(maxIndex + 1);
    }
    return result.toString();
}

