    // Calculate the sum of the values that are less than the average.
    int sumLessThanAvg = 0;
    for (int num : nums) {
        if (num < avg) {
            sumLessThanAvg += num;
        }
    }
    // Calculate the sum of the values that are greater than the average.
    int sumGreaterThanAvg = 0;
    for (int num : nums) {
        if (num > avg) {
            sumGreaterThanAvg += num;
        }
    }
