    return sumLessThanAvg == sumGreaterThanAvg;
}

int minCostClimbingStairs(int[] cost) {
  int currentMinCost = cost[0];
  int previousMinCost = cost[1];
  for (int i = 2; i < cost.length; i++) {
    int temp = currentMinCost;
    currentMinCost = Math.min(currentMinCost, previousMinCost);
    previousMinCost = temp + cost[i];
  }
  return Math.min(currentMinCost, previousMinCost);
}

public int minCostClimbingStairs(int[] cost) {
    int len = cost.length;
    if (len == 2) {
        return Math.min(cost[0], cost[1]);
    }
    int[] dp = new int[len];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < len; i++) {
        dp[i] = Math.min(dp[i - 2] + cost[i], dp[i - 1] + cost[i]);
    }
    return Math.min(dp[len - 2], dp[len - 1]);
}

