}

public int minCostClimbingStairs(int[] cost) {
  int minCost = 0, currentCost = 0;
  int position = 0;
  while (position < cost.length) {
    currentCost = cost[position++];
    if (position < cost.length) {
      int nextCost = cost[position++];
      currentCost += nextCost < currentCost ? nextCost : currentCost;
    }
    minCost += currentCost;
  }
  return minCost;
}

public int minCostClimbingStairs(int[] cost) {

	int currentMinCost = 0;
	int previousMinCost = 0;
	int totalCost = 0;

	for (int i = 0; i < cost.length; i++) {
		currentMinCost = previousMinCost;
		previousMinCost = totalCost;
		totalCost = currentMinCost < previousMinCost ? currentMinCost : previousMinCost;
		totalCost += cost[i];
	}

	return totalCost;
}

