    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else {
            close++;
        }

        if (open > close) {
            min++;
            close++;
        } else if (close > open) {
            min++;
            open++;
        }
    }

    open = close = 0;

    for (int i = s.length() - 1; i >= 0; i--) {
        if (s.charAt(i) == '(') {
            open++;
        } else {
            close++;
        }

        if (open > close) {
            min++;
            close++;
        } else if (close > open) {
            min++;
            open++;
        }
    }

    return min;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    while (true) {
        int x = 0;
        int y = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] != 0) {
                x = i;
                break;
            }
        }
        for (int i = 0; i < n; i++) {
            if (arr[i] != 0) {
                y = i;
                break;
            }
        }
        if (x == y) { // all elements are equal
            return minOperations;
        }
        arr[x] -= 1;
        arr[y] += 1;
        minOperations++;
    }
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] != n) {
            int x = i;
            int y = (i + 1) % n;
            while (arr[x] != n && arr[y] != n) {
                arr[x] -= 1;
                arr[y] += 1;
                minOperations++;
                x = (x + 1) % n;
                y = (y + 1) % n;
            }
        }
    }
    return minOperations;
}

