public int minOperations(int n) {
    // Initialize the array with the given pattern
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    // Keep track of the minimum number of operations
    int minOps = 0;

    // Iterate through the array and perform operations
    for (int i = 0; i < n; i++) {
        // If the current element is not equal to the target value, perform an operation
        int targetValue = (2 * i) + 1;
        if (arr[i] != targetValue) {
            // Compute the difference between the current element and the target value
            int diff = targetValue - arr[i];

            // If the absolute value of the difference is greater than 1, perform a single operation
            if (Math.abs(diff) > 1) {
                minOps++;
            }

            // If the absolute value of the difference is 1, perform two operations
            else {
                minOps += 2;
            }

            // Update the element at the index i to the target value
            arr[i] = targetValue;
        }
    }

    // Return the minimum number of operations
    return minOps;
}

