  }

  int minOperations = 0;
  while (arr.length > 1) {
    for (int i = 0; i < arr.length; i++) {
      if (arr[i] != 1) {
        minOperations++;
        break;
      }
    }

    for (int i = 0; i < arr.length; i++) {
      if (arr[i] == 1) {
        arr[i] = -1;
      }
    }
  }

  return minOperations;
}

