public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer.");
    }

    // Base case: the minimum number of Fibonacci numbers is 1 for any input <= 1
    if (k <= 1) {
        return 1;
    }

    // Initialize the fibonacci series array with the first two numbers
    int[] fibonacciSeries = {1, 1};

    // Iterate through the fibonacci series
    for (int i = 2; i < fibonacciSeries.length; i++) {
        // If the current sum is equal to k, return the current index
        if (fibonacciSeries[i - 1] + fibonacciSeries[i - 2] == k) {
            return i;
        }
        // If the current sum is greater than k, return the previous index
        if (fibonacciSeries[i - 1] + fibonacciSeries[i - 2] > k) {
