        fib[0] = 1;
        fib[1] = 1;
        for (int i = 2; i < k; i++) {
            fib[i] = fib[i - 1] + fib[i - 2];
        }

        // find the minimum number of Fibonacci numbers
        int minNum = Integer.MAX_VALUE;
        for (int i = k - 1; i >= 0; i--) {
            if (fib[i] == k) {
                minNum = 1;
                break;
            } else if (fib[i] < k) {
                minNum = 2;
                break;
            }
        }

        return minNum;
    }

