public int kthFactor(int n, int k) {
    // Check if n and k are valid
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("n and k must be positive");
    }

    // Initialize a list to store all the factors
    List<Integer> factors = new ArrayList<>();

    // Iterate from 1 to the square root of n
    for (int i = 1; i * i <= n; i++) {
        // Check if i divides n evenly
        if (n % i == 0) {
            // If it does, add it to the list of factors
            factors.add(i);

            // If it is not the smallest factor, add the other factor as well
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }

    // Sort the list of factors in ascending order
    factors.sort(Comparator.naturalOrder());

    // Return the kth factor, or -1 if there are fewer than k factors
    return factors.size() < k ? -1 : factors.get(k - 1);
}

