  for (char c : s.toCharArray()) {
    // If the current character is lowercase and the previous character is uppercase
    if (Character.isLowerCase(c) && Character.isUpperCase(previous)) {
      // Add the uppercase version of the current character to the string builder
      sb.append(Character.toUpperCase(c));
    } else {
