public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] count = new int[n];
    int[][] dp = new int[n][n];

    for (int i = 0; i < n; i++) {
        count[i] = 1;
        dp[i][i] = 1;
    }

    for (int i = 0; i < n - 1; i++) {
        if (s.charAt(i) == s.charAt(i + 1)) {
            count[i]++;
            continue;
        }
        for (int j = i + 1; j < n; j++) {
            if (s.charAt(i) == s.charAt(j)) {
                count[j]++;
                dp[i][j] = Math.max(dp[i][j], dp[i + 1][j - 1] + 1);
            } else {
                dp[i][j] = Math.max(dp[i][j], dp[i + 1][j]);
            }
        }
    }

    return dp[0][n - 1];
}

