public int minOperations(String[] logs) {
        Stack<String> folderStack = new Stack<>();
        folderStack.push("/");
        int minSteps = 0;

        for (String log : logs) {
            String folder = folderStack.peek();
            if (log.equals(".")) {
                // no-op
