public String getSmallestString(int n, int k) {
    char[] chars = new char[n];
    int[] positions = new int[n];

    // Calculate the positions of each character in the alphabet
    for (int i = 0; i < n; i++) {
        positions[i] = (int) Math.floor((k - 1) / (Math.pow(26, i)));
        k %= Math.pow(26, i + 1);
    }

    // Calculate the smallest character
    int smallest = 0;
    for (int i = 0; i < n; i++) {
        if (positions[i] < smallest) {
            smallest = positions[i];
        }
    }

    // Convert the positions to characters
    for (int i = 0; i < n; i++) {
        chars[i] = (char) (smallest + 65); // ASCII code for 'A' is 65
        smallest++;
    }

    return new String(chars);
}

public String getSmallestString(int n, int k) {
    if (n == 1) {
        return "" + (char) (k + 'a' - 1);
    }
    String left = getSmallestString(n - 1, k - (n - 1));
    String right = getSmallestString(1, (k - left.length()) + 'a' - 1);
    return left + right;
}

public String getSmallestString(int n, int k) {
    if (n == 1) {
        return String.valueOf((char) (k - 1 + 'a'));
    }
    int mid = n / 2;
    String left = getSmallestString(mid, k);
    String right = getSmallestString(n - mid, k - mid * 26);
    return left + right;
}

