                while (x >= 0 && y >= 0 && mat[x][y] == 1) {
                    curr++;
                    x--;
                    y--;
                }

                x = i;
                y = j;

                while (x < m && y < n && mat[x][y] == 1) {
                    curr++;
                    x++;
                    y++;
                }

                max = Math.max(max, curr);
            }
        }
    }

    return max;
}

public static int longestLine(int[][] mat) {
