    int longestLine = 0;

    // Loop through each row of the matrix
    for (int i = 0; i < mat.length; i++) {
        // Loop through each column of the matrix
        for (int j = 0; j < mat[i].length; j++) {
            // If the current element is 1, then the current line is a possibility
            if (mat[i][j] == 1) {
                // Initialize the length of the current line to 1
                int currentLine = 1;

                // Loop through each row of the matrix, starting from the next row
                for (int k = i + 1; k < mat.length; k++) {
                    // If the element at the current position in the next row is 1, then the current line is a possibility
                    if (mat[k][j] == 1) {
                        // Increment the length of the current line
                        currentLine++;
                    } else {
                        // If the element at the current position in the next row is 0, then the current line is not a possibility
                        break;
                    }
                }

                // Loop through each column of the matrix, starting from the next column
                for (int l = j + 1; l < mat[i].length; l++) {
                    // If the element at the current position in the next column is 1, then the current line is a possibility
                    if (mat[i][l] == 1) {
                        // Increment the length of the current line
                        currentLine++;
                    } else {
                        // If the element at the current position in the next column is 0, then the current line is not a possibility
                        break;
                    }
                }

                // Update the length of the longest line if the current line is longer
                longestLine = Math.max(longestLine, currentLine);
            }
        }
