public static int longestLine(int[][] mat) {
    // Initialize variables
    int longestLineLength = 0;
    int currentLineLength = 0;
    int currentLineStart = 0;
    boolean isInCurrentLine = false;

    // Loop through each cell in the matrix
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[i].length; j++) {
            // If the current cell is 1, start a new line if necessary
            if (mat[i][j] == 1) {
                if (!isInCurrentLine) {
                    currentLineLength = 1;
                    currentLineStart = i;
                    isInCurrentLine = true;
                } else {
                    currentLineLength++;
                }
            // If the current cell is 0 or the end of the line is reached, end the current line
            } else {
                if (isInCurrentLine) {
                    longestLineLength = Math.max(longestLineLength, currentLineLength);
                    isInCurrentLine = false;
                }
            }
        }
    }

    // If the last line was not ended, end it
    if (isInCurrentLine) {
        longestLineLength = Math.max(longestLineLength, currentLineLength);
    }

    return longestLineLength;
}

