    int numDigits = (int) Math.log10(n) + 1;

    // Iterate through the digits of the input
    for (int i = 0; i < numDigits; i++) {
        // Get the current digit
        int digit = n % 10;

        // Add the digit to the result string
        result = digit + result;

        // Check if we need to add a dot separator
        if (i % 3 == 0 && i != 0) {
            result = "." + result;
        }

