private static int countSquarePermutations(int[] A) {
        int count = 0;
        for (int i = 0; i < A.length; i++) {
            if (A[i] % 2 == 0) {
                count++;
            }
        }
        if (count == A.length) {
            return 1;
        }
        for (int i = 0; i < A.length; i++) {
            if (A[i] % 2 == 0 && isSquare(A[i])) {
                int j = i + 1;
                while (j < A.length && A[j] % 2 == 0 && !isSquare(A[j])) {
                    j++;
                }
                if (j == A.length) {
                    return 0;
                }
                int temp = A[i];
                A[i] = A[j];
                A[j] = temp;
            }
        }
        return countSquarePermutations(A);
    }

private static boolean isSquare(int n) {
        int k = (int) Math.round(Math.sqrt(n));
        return k * k == n;
    }

public static int squarePermutations(int[] A) {
    // Check if the input array is null or has negative elements
    if (A == null || A.length == 0 || A.stream().anyMatch(x -> x < 0)) {
        throw new IllegalArgumentException("Invalid input array");
    }

    // Initialize a set to store the permutations
    Set<int[]> permutations = new HashSet<>();

    // Calculate the number of square permutations
    int numPermutations = 1;
    for (int i = 0; i < A.length; i++) {
        // Calculate the sum of the adjacent elements in the array
        int sum = 0;
        if (i > 0) {
            sum += A[i - 1];
        }
        if (i < A.length - 1) {
            sum += A[i + 1];
        }

        // Check if the sum is a perfect square
        int root = (int) Math.sqrt(sum);
        if (root * root == sum) {
            // If the sum is a perfect square, then the permutation is valid
            numPermutations++;

            // Add the permutation to the set
            permutations.add(Arrays.copyOf(A, A.length));
        }
    }

    // Return the number of square permutations
    return numPermutations;
}

public static int squarePermutations(int[] A) {
  // Signature: squarePermutations(int[] A) -> int
  // Purpose: Given a non-negative integer array A, if the sum of each pair of adjacent elements in the array is a perfect square, then the array is considered a square array.
  // Return the number of square permutations of A. Two permutations A1 and A2 are considered different if there exists an index i such that A1[i] != A2[i].
  // Parameters:
  //  A (int[]): The non-negative integer array.
  // Returns:
  //  (int): The number of square permutations of A.

  // Edge cases:
  // - Invalid parameters: No need to handle any edge cases in this method as the input is already validated to be a non-null and non-empty integer array.

  int[] permutations = new int[A.length]; // Initialize an array to store the permutations
  int permutationCount = 1; // Initialize the number of square permutations to 1

  // Iterate through the array and generate permutations
  for (int i = 0; i < A.length; i++) {
    permutations[i] = A[i]; // Initialize the current permutation with the current element

    // Iterate through the rest of the array and generate the remaining permutations
    for (int j = i + 1; j < A.length; j++) {
      permutations[j] = A[j]; // Update the permutation with the next element

      // Check if the permutation is a square
      if (isSquare(permutations)) {
        permutationCount++; // Increment the number of square permutations
      }
    }
  }

  return permutationCount;
}

private static boolean isSquare(int[] permutation) {
  // Signature: isSquare(int[] permutation) -> boolean
  // Purpose: Check if a given permutation of an array is a square sum.
  // Parameters:
  //  permutation (int[]): The permutation of the array.
  // Returns:
  //  (boolean): True if the permutation is a square sum, false otherwise.

  // Edge cases:
  // - Invalid parameters: No need to handle any edge cases in this method as the input is already validated to be a non-null and non-empty integer array.

  int sum = 0; // Initialize the sum to 0

  // Calculate the sum of the adjacent elements in the permutation
  for (int i = 0; i < permutation.length - 1; i++) {
    sum += permutation[i] + permutation[i + 1];
  }

  // Check if the sum is a perfect square
  return Math.sqrt(sum) % 1 == 0;
}

