public static int largestRectangleArea(int[] heights) {
    int largestRectangleArea = 0;
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < heights.length; i++) {
        int currentHeight = heights[i];
        if (stack.empty()) {
            stack.push(currentHeight);
        } else {
            int topOfStack = stack.peek();
            if (currentHeight > topOfStack) {
                stack.push(currentHeight);
            } else {
                while (!stack.empty() && stack.peek() > currentHeight) {
                    int poppedHeight = stack.pop();
                    largestRectangleArea = Math.max(largestRectangleArea, poppedHeight * (i - stack.peek() - 1));
                }
                stack.push(currentHeight);
            }
        }
    }
    while (!stack.empty()) {
        int poppedHeight = stack.pop();
        largestRectangleArea = Math.max(largestRectangleArea, poppedHeight * (heights.length - stack.peek() - 1));
    }
    return largestRectangleArea;
}

public static int largestRectangleArea(int[] heights) {
    // Step 1: Calculate the area of each possible rectangle
    int[] areas = new int[heights.length];
    for (int i = 0; i < heights.length; i++) {
        areas[i] = heights[i] * (i + 1);
    }

    // Step 2: Find the maximum area
    int maxArea = 0;
    for (int i = 0; i < areas.length; i++) {
        int height = heights[i];
        if (height == 0) {
            continue;
        }
        int width = 1;
        while (i + width < areas.length && heights[i + width] >= height) {
            width++;
        }
        maxArea = Math.max(maxArea, areas[i] * width);
    }

    return maxArea;
}

