public static int findSmallestInteger(int n) {
    // Step 1: Sort the digits of n in ascending order
    int[] sortedDigits = sortDigits(n);
    // Step 2: Check if n is already the smallest rearranged integer
    if (n == getRearrangedNumber(sortedDigits)) return n;
    // Step 3: Find the smallest rearranged integer by iterating through the digits
    for (int i = 0; i < sortedDigits.length; i++) {
        // Step 4: Swap the current digit with the one at the end of the sorted array
        int temp = sortedDigits[i];
        sortedDigits[i] = sortedDigits[sortedDigits.length - 1];
        sortedDigits[sortedDigits.length - 1] = temp;
        // Step 5: Check if the rearranged number is greater than n
        int rearrangedNumber = getRearrangedNumber(sortedDigits);
        if (rearrangedNumber > n) continue;
        // Step 6: Check if the rearranged number is the smallest one
        if (rearrangedNumber < n) {
            return rearrangedNumber;
        }
    }
    // Step 7: Return -1 if no smaller rearranged number was found
    return -1;
}

private static int getRearrangedNumber(int[] digits) {
    int result = 0;
    for (int digit : digits) {
        result = result * 10 + digit;
    }
    return result;
}

