public static boolean isBoomerang(int[][] points) {
    // Step 1: Sort the points based on the x-coordinate
    Arrays.sort(points, Comparator.comparingInt(point -> point[0]));

    // Step 2: Check if the points are in a counterclockwise order
    int area = getArea(points);
    if (area == 0) {
        return false;
    }

    // Step 3: Check if the points form a boomerang
    int i = 0;
    int j = points.length - 1;
    while (i < j) {
        if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
            return false;
        }
        i++;
        j--;
    }

    return true;
}

private static int getArea(int[][] points) {
    int area = 0;
    for (int i = 1; i < points.length - 1; i++) {
        area += (points[i][1] - points[0][1]) * (points[i][0] - points[points.length - 1][0]);
    }
    return area;
}

