    sortPoints(points, 0);

    // Check if the first and last points are the same
    if (points[0][0] == points[points.length - 1][0] && points[0][1] == points[points.length - 1][1]) {
        return false;
    }

    // Iterate over the points and check if the angle between any two consecutive points is greater than 180 degrees
    for (int i = 0; i < points.length - 2; i++) {
        int[] point1 = points[i];
        int[] point2 = points[i + 1];
        int[] point3 = points[i + 2];

        double angle = getAngle(point1, point2, point3);
        if (angle > 180) {
            return true;
        }
    }

    return false;
}

public static void sortPoints(int[][] points, int index) {
    // Check if the points are not null or empty
    if (points == null || points.length == 0) {
        return;
    }

    // Sort the points by the given index
    Arrays.sort(points, new Comparator<int[]>() {
        public int compare(int[] point1, int[] point2) {
            return point1[index] - point2[index];
        }
    });
}

