public static double getAngle(int[] point1, int[] point2, int[] point3) {
    // Compute the lengths of the two segments
    double len1 = distance(point1, point2);
    double len2 = distance(point2, point3);

    // Compute the dot product
    double dot = (point1[0] - point2[0]) * (point2[0] - point3[0]) + (point1[1] - point2[1]) * (point2[1] - point3[1]);

    // Compute the angle
    double angle = Math.acos(dot / (len1 * len2)) * (180.0 / Math.PI);

    // Return the angle
    return angle;
}

public static double distance(int[] point1, int[] point2) {
    // Compute the differences
    double dx = point1[0] - point2[0];
    double dy = point1[1] - point2[1];

    // Compute the square of the sum
    double distSq = dx * dx + dy * dy;

    // Return the square root of the sum
    return Math.sqrt(distSq);
}

public static int findNthUglyNumber(int n) {
    int[] dp = new int[n+1];
    dp[1] = 1;
    int i2 = 1, i3 = 1, i5 = 1;
    for (int i = 2; i <= n; i++) {
        int nextUglyNumber = Math.min(dp[i2] * 2, Math.min(dp[i3] * 3, dp[i5] * 5));
        dp[i] = nextUglyNumber;
        if (nextUglyNumber == dp[i2] * 2) i2++;
        if (nextUglyNumber == dp[i3] * 3) i3++;
        if (nextUglyNumber == dp[i5] * 5) i5++;
    }
    return dp[n];
}

