    }

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }

    // Initialize an array to store the ugly numbers
    int[] uglyNumbers = new int[n];

    // Initialize the first ugly number
    uglyNumbers[0] = 1;

    // Initialize the indices of the multipliers for 2, 3, and 5
    int i2 = 0;
    int i3 = 0;
    int i5 = 0;

    // Loop until all ugly numbers have been generated
    for (int i = 1; i < n; i++) {
        // Calculate the next ugly number
        int nextUglyNumber = Math.min(
            uglyNumbers[i2] * 2,
            Math.min(uglyNumbers[i3] * 3, uglyNumbers[i5] * 5));

        // Update the array with the next ugly number
        uglyNumbers[i] = nextUglyNumber;

        // Update the indices of the multipliers
        if (nextUglyNumber == uglyNumbers[i2] * 2) {
            i2++;
        }
        if (nextUglyNumber == uglyNumbers[i3] * 3) {
            i3++;
        }
        if (nextUglyNumber == uglyNumbers[i5] * 5) {
            i5++;
        }
    }

    return uglyNumbers[n - 1];
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The argument must be a positive integer.");
    }

    Queue<Integer> que = new LinkedList<>();
    que.offer(1);

    int count = 1;

    while (que.size() < n) {
        int num = que.poll();
        for (int i = num * 2; i < Integer.MAX_VALUE; i *= 2) {
            if (num % i != 0) {
                que.offer(i);
            }
        }
        for (int i = num * 3; i < Integer.MAX_VALUE; i *= 3) {
            if (num % i != 0) {
                que.offer(i);
            }
        }
        for (int i = num * 5; i < Integer.MAX_VALUE; i *= 5) {
            if (num % i != 0) {
                que.offer(i);
            }
        }
    }

    return que.poll();
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }

    int[] primes = {2, 3, 5};
    int[] pgcd = {2, 3, 5};

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    for (int i = 1; i < n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 0; j < 3; j++) {
            int product = primes[j] * pgcd[j];
            if (product < min && uglyNumbers[i - 1] == product) {
                min = product;
            }
        }
        uglyNumbers[i] = min;
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() < 1) {
      return 0;
    }
    int longest = 0;
    int current = 0;
    for (int i = 0; i < s.length(); i++) {
      if (s.charAt(i) != s.charAt(i - 1) && longest < current) {
        longest = current;
      }
      if (s.charAt(i) == s.charAt(i - 1)) {
        current++;
      } else {
        current = 1;
      }
    }
    return longest;
  }

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int energy = 0, maxEnergy = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (i > 0 && s.charAt(i - 1) == c) {
            energy++;
        } else {
            energy = 1;
        }

        if (energy > maxEnergy) {
            maxEnergy = energy;
        }
    }

    return maxEnergy;
}

public static int calculateEnergy(String s) {
    if (s.length() == 0) {
        return 0;
    }

    int energy = 0;
    int maxEnergy = 0;
    int currentEnergy = 1;
    boolean wasPreviousCharSame = false;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            if (!wasPreviousCharSame) {
                currentEnergy++;
                wasPreviousCharSame = true;
            }
        } else {
            if (wasPreviousCharSame) {
                maxEnergy = Math.max(energy, maxEnergy);
                energy = currentEnergy;
                currentEnergy = 1;
                wasPreviousCharSame = false;
            } else {
                currentEnergy++;
            }
        }
    }

    maxEnergy = Math.max(energy, maxEnergy);
    return maxEnergy;
}

