    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (Math.sqrt(i) == (int)Math.sqrt(i)) {
            count++;
        }
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        int temp = n - i * i;
        int roots = (int) Math.floor(Math.sqrt(temp));
        if (roots * roots == temp) {
            count++;
        } else {
            count += 2;
        }
    }
    return count;
}

